  return parseAppConfigSections(
    userDoc: userDoc,
    projectDoc: projectDoc,
    projectRulesDoc: projectRulesDoc,
    userSource: userPath,
    projectSource: projectConfigPath ?? '.fah/config.yaml',
    projectRulesSource: projectRulesPath ?? '.fah/rules.yaml',
