 /// The ACTIVE model's context-window provenance (gh-2479): the
 /// effective (cap-aplied) window, the layer it came from, the pre-cap
 /// value and the owner cap. Null when no connection is resolved yet
 /// (the pre-constructed-agent test constructor without a reconfigure).
 ({int window, CapabilityWindowLayer source, int uncapped, int? cap})?
 get modelContextWindow {
   final base = _activeConfigWindow;
   if (base == null) return null;
   final provider = _agent.state.model.provider;
   final modelId = _agent.state.model.id;
   final spec = catalogProvider(provider);
   // The endpoint layer contributes only when the carried value is NOT
   // the spec default (an endpoint report equal to the spec value adds
   // no information; the provenance stays the spec layer).
   final endpoint = base == spec?.contextWindow ? null : base;
   final caps = resolveModelCapabilities(
     provider: provider,
     modelId: modelId,
     override: modelCapabilityOverrides?.lookup(provider, modelId),
     endpointContextWindow: endpoint,
     spec: spec,
     api: spec?.api,
     reasoning: spec?.reasoning ?? true,
     contextWindowCap: _contextWindowCap,
   );
   return (
     window: caps.contextWindow,
     source: caps.contextWindowSource,
     uncapped: caps.contextWindowUncapped ?? base,
     cap: _contextWindowCap,
   );
 }
``

