      modelId: model.id,
      override: modelCapabilityOverrides?.lookup(model.provider, model.id),
      endpointContextWindow: endpoint,
      spec: spec,
      api: spec?.api,
      reasoning: spec?.reasoning ?? true,
      contextWindowCap: _contextWindowCap,
