import zlib, struct
def png_pixels(path):
    data = open(path, 'rb').read()
    pos = 8; idat = b''; w = h = None
    while pos < len(data):
        ln, typ = struct.unpack('>I4s', data[pos:pos+8])
        chunk = data[pos+8:pos+8+ln]
        if typ == b'IHDR': w, h = struct.unpack('>II', chunk[:8])
        elif typ == b'IDAT': idat += chunk
        pos += 12 + ln
    raw = zlib.decompress(idat)
    stride = w*3+1
    pixels = bytearray(); prev = bytearray(w*3); i = 0
    for y in range(h):
        f = raw[i]; line = bytearray(raw[i+1:i+stride]); i += stride
        if f == 1:
            for x in range(3, len(line)): line[x] = (line[x] + line[x-3]) & 255
        elif f == 2:
            for x in range(len(line)): line[x] = (line[x] + prev[x]) & 255
        elif f == 3:
            for x in range(len(line)):
                a = line[x-3] if x >= 3 else 0
                line[x] = (line[x] + ((a + prev[x]) >> 1)) & 255
        elif f == 4:
            for x in range(len(line)):
                a = line[x-3] if x >= 3 else 0
                b = prev[x]; c = prev[x-3] if x >= 3 else 0
                p = a + b - c
                pa, pb, pc = abs(p-a), abs(p-b), abs(p-c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                line[x] = (line[x] + pr) & 255
        pixels += line; prev = line
    return w, h, bytes(pixels)

